-- PT115-S2-Q4. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT115-S2-Q4$batch06$ AND q.stimulus=$batch06$Marie: I gave the cashier at my local convenience store a 10-dollar bill to pay for my purchase, and he mistakenly gave me change for a 20-dollar bill. I kept the extra 10 dollars. Since I did not trick, threaten, or physically force the cashier into giving me the extra money, it was not morally wrong for me to keep it.
Julia: Nonsense. If you mistakenly hand me your coat, thinking it is my coat, then even though I did not get the coat by means of any deception, threats, or violence against you, I am not morally entitled to keep it for myself.$batch06$ AND q.prompt=$batch06$Julia's response functions in which one of the following ways?$batch06$ AND q.correct_choice=$batch06$C$batch06$) THEN RAISE EXCEPTION 'Question changed: PT115-S2-Q4'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT115-S2-Q4$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S2-Q4'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT115-S2-Q4$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$(Julia, implied) Marie was wrong to keep the money.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$If someone mistakenly hands you their coat, you are not entitled to keep it, even though you used no trickery, threats or force.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$Marie's principle is that without deception, threats or force, keeping something is fine. Julia builds a case that meets all of Marie's conditions (no trickery, no threats, no force) where keeping the item is clearly wrong. The coat case is just like Marie's, and it points the other way.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Challenging Marie's conclusion with a similar case where the opposite conclusion is clearly right.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT115-S2-Q4$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$Julia does not accept Marie's principle. Her coat case shows the principle itself is wrong.$batch06$), ($batch06$B$batch06$, $batch06$Julia argues against Marie, not for her.$batch06$), ($batch06$C$batch06$, $batch06$The coat case is relevantly similar: a mistaken handover, with no trickery. And the right conclusion there is the opposite of Marie's.$batch06$), ($batch06$D$batch06$, $batch06$Julia is not solving a problem of her own.$batch06$), ($batch06$E$batch06$, $batch06$Julia does not hold back judgment. "Nonsense" makes her verdict clear.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT115-S2-Q4$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
